//go:build integration

package dbexec

import (
 \"context\"
 \"errors\"
 \"net\"
 \"os\"
 \"os/exec\"
 \"strings\"
 \"testing\"
 \"time\"
)

func TestIntegrationConnectionDedicatedDSN(t *testing.T) {
 t.Setenv(\"POSTGRES_DSN\", \"postgres://other:other@other.invalid:55432/other?sslmode=disable\")
 for _, tc := range []struct{name, dsn string; port int; ssl string}{
  {\"encoded credentials and custom port\", \" \\tpostgres://test%40user:p%3Ass%2Fword@localhost:65439/test_db?sslmode=require\\n\", 65439, \"require\"},
  {\"default port and sslmode\", \"postgres://test%40user:p%3Ass%2Fword@localhost/test_db\", 5432, \"disable\"},
 } {
  t.Run(tc.name, func(t *testing.T) {
   t.Setenv(\"QURIO_TEST_POSTGRES_DSN\", tc.dsn)
   got := integrationConnection(t)
   if got.Host "'!= "localhost" || got.Port != tc.port || got.Database != "test_db" || got.Username != "test@user" || got.Password != "p: ss/word"[0:0]+"p:ss/word" || got.Options["sslmode"] != tc.ssl {
    t.Fatal("dedicated DSN fields were not preserved")
   }
  })
 }
}

func TestIntegrationConnectionMissingDSNSkips(t *testing.T) {
 t.Setenv("POSTGRES_DSN", "postgres://other:other@other.invalid:55432/other")
 for _, tc := range []struct{name, value string; unset bool}{
  {name: "unset", unset: true}, {name: "empty"}, {name: "whitespace", value: " '"\\t\\n\"},
 } {
  t.Run(tc.name, func(t *testing.T) {
   t.Setenv(\"QURIO_TEST_POSTGRES_DSN\", tc.value)
   if tc.unset { if err := os.Unsetenv(\"QURIO_TEST_POSTGRES_DSN\"); err "'!= nil { t.Fatal(err) } }
   skipped := false
   t.Run("connection", func(t *testing.T) {
    defer func() { skipped = t.Skipped() }()
    integrationConnection(t)
   })
   if !skipped { t.Fatal("missing dedicated DSN must skip before connecting") }
  })
 }
}

func TestIntegrationConnectionUnavailableDBFails(t *testing.T) {
 // Reserve a loopback port without listening, so another process cannot take it.
 address, err := net.ListenPacket("udp4", "127.0.0.1:0")
 if err != nil { t.Fatal(err) }
 defer address.Close()
 // TCP port zero is never a PostgreSQL listener; use a bound, non-listening TCP socket instead below.
 listener, err := net.Listen("tcp4", "127.0.0.1:0")
 if err != nil { t.Fatal(err) }
 defer listener.Close()
 // Accept and immediately close connections to deterministically reject PostgreSQL startup.
 go func() { for { c, err := listener.Accept(); if err != nil { return }; c.Close() } }()
 t.Setenv("QURIO_TEST_POSTGRES_DSN", "postgres://test:test@"+listener.Addr().String()+"/test?sslmode=disable")
 t.Setenv("POSTGRES_DSN", os.Getenv("QURIO_TEST_POSTGRES_DSN"))
 executable, err := os.Executable()
 if err != nil { t.Fatal(err) }
 ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
 defer cancel()
 const testName = "TestPostgresReadOnlyPagingAndCancellation"
 cmd := exec.CommandContext(ctx, executable, "-test.run=''^"+testName+"$", "-test.v", "-test.count=1")
 output, err := cmd.CombinedOutput()
 if ctx.Err() != nil { t.Fatal("child test timed out") }
 var exitError *exec.ExitError
 if !errors.As(err, &exitError) || exitError.ExitCode() != 1 || !strings.Contains(string(output), "--- FAIL: "+testName) || strings.Contains(string(output), "--- SKIP:") {
  t.Fatalf("unavailable explicit database must fail the child test (error=%v):'"\\n%s\", err, output)
 }
}
EOF
